/***********************************************************************************************
 * CDFC::Add_Search_Drive -- Add a new path to the search path list                            *
 *                                                                                             *
 *                                                                                             *
 *                                                                                             *
 * INPUT:    path                                                                              *
 *                                                                                             *
 * OUTPUT:   Nothing                                                                           *
 *                                                                                             *
 * WARNINGS: None                                                                              *
 *                                                                                             *
 * HISTORY:                                                                                    *
 *    5/22/96 10:12AM ST : Created                                                             *
 *=============================================================================================*/
void CDFileClass::Add_Search_Drive(char *path)
{
	char normalized[_MAX_PATH];
	char const *paths[2];
	int count = 1;

	paths[0] = normalized;
	paths[1] = NULL;

	strncpy(normalized, path, sizeof(normalized) - 1);
	normalized[sizeof(normalized) - 1] = '\0';

	for (char *ptr = normalized; *ptr; ++ptr) {
		if (*ptr == '\\') {
			*ptr = '/';
		}
	}

	if (normalized[1] == ':' && (normalized[2] == '/' || normalized[2] == '\0')) {
		switch (toupper(normalized[0])) {
			case 'C':
				paths[0] = "assets/redalert/allies/";
				paths[1] = "assets/redalert/allies/INSTALL/";
				count = 2;
				break;

			case 'D':
				paths[0] = "assets/redalert/soviet/";
				paths[1] = "assets/redalert/soviet/INSTALL/";
				count = 2;
				break;
		}
	}

	for (int index = 0; index < count; ++index) {
		SearchDriveType *srch;					// Working pointer to path object.
		/*
		**	Allocate a record structure.
		*/
		srch	= new SearchDriveType;

		/*
		**	Attach the path to this structure.
		*/
		srch->Path = strdup(paths[index]);
		srch->Next = NULL;

		/*
		**	Attach this path record to the end of the path chain.
		*/
		if (!First) {
			First = srch;
		} else {
			SearchDriveType * chain = First;

			while (chain->Next) {
				chain = (SearchDriveType *)chain->Next;
			}
			chain->Next = srch;
		}
	}
}
