  if (!status.hasMix) return getString(R.string.not_imported);
  String base = status.fileCount + " files • " + GameDataStore.formatBytes(status.byteCount);
  if (!status.hasMainMix) base += " • missing " + GameDataInspector.MAIN_MIX;
  else base += " • " + getString(R.string.ready);
  if (!status.hasConfig) base += " • settings will be generated";
