package com.vanillara.redalert;

import android.annotation.TargetApi;
import android.content.Intent;
import android.os.Build;
import android.os.Bundle;
import android.os.SystemClock;
import android.view.KeyEvent;
import android.view.View;
import android.view.Window;
import android.view.WindowInsets;
import android.view.WindowInsetsController;
import android.view.WindowManager;
import android.window.OnBackInvokedCallback;
import android.window.OnBackInvokedDispatcher;

import org.libsdl.app.SDLActivity;

/**
 * Hosts the native Red Alert engine. The game data has already been imported
 * into app-private storage by SetupActivity.
 */
public class RedAlertActivity extends SDLActivity {

    @Override
    protected String[] getLibraries() {
        return new String[] {"SDL2", "main"};
    }

    @Override
    protected String getMainFunction() {
        return "SDL_main";
    }

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        if (!GameDataStore.prepareForLaunch(this)) {
            startActivity(new Intent(this, SetupActivity.class));
            finish();
            return;
        }
        configureImmersiveMode();
        super.onCreate(savedInstanceState);
        registerBackCallback();
        configureImmersiveMode();
    }

    @Override
    protected void onResume() {
        super.onResume();
        configureImmersiveMode();
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) {
            configureImmersiveMode();
        }
    }

    private void registerBackCallback() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            registerOnBackInvokedCallback();
        }
    }

    @TargetApi(Build.VERSION_CODES.TIRAMISU)
    private void registerOnBackInvokedCallback() {
        getOnBackInvokedDispatcher().registerOnBackInvokedCallback(
            OnBackInvokedDispatcher.PRIORITY_DEFAULT,
            new OnBackInvokedCallback() {
                @Override
                public void onBackInvoked() {
                    sendEscapePulse();
                }
            }
        );
    }

    private void configureImmersiveMode() {
        Window window = getWindow();
        window.addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            WindowManager.LayoutParams attributes = window.getAttributes();
            attributes.layoutInDisplayCutoutMode =
                WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
            window.setAttributes(attributes);
        }

        View decorView = window.getDecorView();
        decorView.setSystemUiVisibility(
            View.SYSTEM_UI_FLAG_FULLSCREEN
                | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
                | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
                | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
                | View.SYSTEM_UI_FLAG_LAYOUT_STABLE
        );

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            window.setDecorFitsSystemWindows(false);
            WindowInsetsController controller = decorView.getWindowInsetsController();
            if (controller != null) {
                controller.setSystemBarsBehavior(
                    WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
                controller.hide(WindowInsets.Type.statusBars() | WindowInsets.Type.navigationBars());
            }
        }
    }

    @Override
    public void onBackPressed() {
        sendEscapePulse();
    }

    @Override
    public boolean dispatchKeyEvent(KeyEvent event) {
        if (event.getKeyCode() == KeyEvent.KEYCODE_BACK) {
            KeyEvent escapeEvent = new KeyEvent(
                event.getDownTime(),
                event.getEventTime(),
                event.getAction(),
                KeyEvent.KEYCODE_ESCAPE,
                event.getRepeatCount(),
                event.getMetaState(),
                event.getDeviceId(),
                event.getScanCode(),
                event.getFlags(),
                event.getSource()
            );
            super.dispatchKeyEvent(escapeEvent);
            return true;
        }
        return super.dispatchKeyEvent(event);
    }

    private void sendEscapePulse() {
        long now = SystemClock.uptimeMillis();
        dispatchKeyEvent(new KeyEvent(now, now, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_ESCAPE, 0));
        dispatchKeyEvent(new KeyEvent(now, now, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_ESCAPE, 0));
    }
}

#include <SDL.h>
#include <SDL_system.h>

#include <limits.h>
#include <string>
#include <string.h>
#include <sys/stat.h>
#include <stdio.h>
#include <unistd.h>

#include <windows.h>

int PASCAL WinMain(HINSTANCE instance, HINSTANCE previous, char *command_line, int command_show);

static bool path_exists(char const *path)
{
    struct stat info;
    return path && stat(path, &info) == 0;
}

static bool select_resource_root(void)
{
    static char const *config_path = "assets/redalert/allies/INSTALL/REDALERT.INI";
    if (path_exists(config_path)) {
        return true;
    }

    char const *internal_path = SDL_AndroidGetInternalStoragePath();
    if (!internal_path || !internal_path[0]) {
        return false;
    }

    std::string resource_root = std::string(internal_path) + "/redalert-root";
    if (chdir(resource_root.c_str()) != 0) {
        return false;
    }
    return path_exists(config_path);
}

extern "C" int SDL_main(int argc, char **argv)
{
    if (!select_resource_root()) {
        SDL_Log("Vanillara: no imported Red Alert data found in app storage.");
        return 1;
    }

    std::string command_line;
    for (int index = 1; index < argc; ++index) {
        if (!command_line.empty()) {
            command_line += ' ';
        }
        command_line += argv[index];
    }

    int result = WinMain((HINSTANCE)0, (HINSTANCE)0, command_line.empty() ? (char *)"" : (char *)command_line.c_str(), SW_RESTORE);

    /*
    **	The 1996 codebase assumes the process dies when the game exits: it keeps
    **	global state (_Mouse, Screen, the DirectDraw surfaces, the mixfile heaps)
    **	that is never torn down or re-initialised. Android, however, keeps the
    **	process alive after the activity finishes, so launching again re-enters
    **	SDL_main() against those stale globals and segfaults immediately --
    **	Block_Mouse() dereferences _Mouse->Screen, which points at freed memory.
    **
    **	Terminate the process instead so the next launch starts clean. _exit()
    **	rather than exit() because the static destructors belong to that same
    **	un-resettable global state and are not safe to run here; flush first so
    **	anything the game buffered on the way out still lands.
    */
    fflush(NULL);
    _exit(result);
}

package com.vanillara.redalert;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.FileOutputStream;

public class GameDataInspectorTest {

    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void emptyFolderIsNotPlayable() throws Exception {
        File side = temporary.newFolder("allies");
        GameDataInspector.Status status = GameDataInspector.inspect(side);
        assertFalse(status.hasMix);
        assertFalse(status.hasMainMix);
        assertFalse(status.isPlayable());
        assertEquals(0, status.fileCount);
    }

    @Test
    public void mainMixMakesSidePlayable() throws Exception {
        File side = temporary.newFolder("allies");
        File install = new File(side, "INSTALL");
        assertTrue(install.mkdirs());
        write(new File(install, "REDALERT.INI"), "[Options]\n");
        write(new File(side, "REDALERT.MIX"), "mix");
        write(new File(side, "CONQUER.MIX"), "mix");

        GameDataInspector.Status status = GameDataInspector.inspect(side);
        assertTrue(status.hasMix);
        assertTrue(status.hasMainMix);
        assertTrue(status.hasConfig);
        assertTrue(status.isPlayable());
        assertEquals(3, status.fileCount);
    }

    @Test
    public void unrelatedMixIsNotPlayable() throws Exception {
        File side = temporary.newFolder("allies");
        write(new File(side, "MOVIES1.MIX"), "mix");
        GameDataInspector.Status status = GameDataInspector.inspect(side);
        assertTrue(status.hasMix);
        assertFalse(status.hasMainMix);
        assertFalse(status.isPlayable());
    }

    @Test
    public void normalizeSegmentUppercasesAndRemovesSeparators() {
        assertEquals("REDALERT.MIX", GameDataInspector.normalizeSegment("redalert.mix"));
        assertEquals("A_B", GameDataInspector.normalizeSegment("a/b"));
        assertEquals("_", GameDataInspector.normalizeSegment(".."));
        assertEquals("_", GameDataInspector.normalizeSegment("  "));
    }

    @Test
    public void discImagesAndArchivesAreBlocked() {
        assertTrue(GameDataInspector.isBlockedFile("game.iso"));
        assertTrue(GameDataInspector.isBlockedFile("allies.bin"));
        assertTrue(GameDataInspector.isBlockedFile("backup.zip"));
        assertFalse(GameDataInspector.isBlockedFile("REDALERT.MIX"));
        assertFalse(GameDataInspector.isBlockedFile("INSTALL"));
    }

    @Test
    public void ensureConfigMirrorsRootIni() throws Exception {
        File side = temporary.newFolder("allies");
        write(new File(side, "REDALERT.INI"), "[Options]\nGameSpeed=5\n");

        assertTrue(GameDataInspector.ensureConfig(side));
        assertTrue(new File(side, "INSTALL/REDALERT.INI").isFile());
        assertTrue(GameDataInspector.inspect(side).hasConfig);
        assertFalse(GameDataInspector.ensureConfig(side));
    }

    @Test
    public void ensureConfigCreatesMinimalIni() throws Exception {
        File side = temporary.newFolder("soviet");
        assertTrue(GameDataInspector.ensureConfig(side));
        File config = new File(side, "INSTALL/REDALERT.INI");
        assertTrue(config.isFile());
        assertTrue(config.length() > 0);
    }

    @Test
    public void deleteTreeRemovesNestedData() throws Exception {
        File root = temporary.newFolder("redalert-root");
        File nested = new File(root, "assets/redalert/allies");
        assertTrue(nested.mkdirs());
        write(new File(nested, "REDALERT.MIX"), "mix");
        GameDataInspector.deleteTree(root);
        assertFalse(root.exists());
    }

    private static void write(File file, String contents) throws Exception {
        try (FileOutputStream output = new FileOutputStream(file)) {
            output.write(contents.getBytes("UTF-8"));
        }
    }
}

