#include <SDL.h>
#include <SDL_system.h>

#include <limits.h>
#include <string>
#include <string.h>
#include <sys/stat.h>
#include <stdio.h>
#include <unistd.h>

#include <windows.h>

int PASCAL WinMain(HINSTANCE instance, HINSTANCE previous, char *command_line, int command_show);

static bool path_exists(char const *path)
{
    struct stat info;
    return path && stat(path, &info) == 0;
}

static bool try_resource_root(char const *base)
{
    static char const *config_path = "assets/redalert/allies/INSTALL/REDALERT.INI";
    if (!base || !base[0]) {
        return false;
    }

    std::string resource_root = std::string(base) + "/redalert-root";
    if (chdir(resource_root.c_str()) != 0) {
        return false;
    }
    return path_exists(config_path);
}

static bool select_resource_root(void)
{
    static char const *config_path = "assets/redalert/allies/INSTALL/REDALERT.INI";
    if (path_exists(config_path)) {
        return true;
    }

    /*
    ** The Java importer creates folders in app-specific external storage so
    ** the player can copy game files over USB or with a file manager. Prefer
    ** that location; fall back to internal storage when external storage is
    ** unavailable or was not populated.
    */
    if (try_resource_root(SDL_AndroidGetExternalStoragePath())) {
        return true;
    }
    if (try_resource_root(SDL_AndroidGetInternalStoragePath())) {
        return true;
    }
    return false;
}

extern "C" int SDL_main(int argc, char **argv)
{
    if (!select_resource_root()) {
        SDL_Log("Vanillara: no imported Red Alert data found in app storage.");
        return 1;
    }

    std::string command_line;
    for (int index = 1; index < argc; ++index) {
        if (!command_line.empty()) {
            command_line += ' ';
        }
        command_line += argv[index];
    }

    int result = WinMain((HINSTANCE)0, (HINSTANCE)0, command_line.empty() ? (char *)"" : (char *)command_line.c_str(), SW_RESTORE);

    /*
    **	The 1996 codebase assumes the process dies when the game exits: it keeps
    **	global state (_Mouse, Screen, the DirectDraw surfaces, the mixfile heaps)
    **	that is never torn down or re-initialised. Android, however, keeps the
    **	process alive after the activity finishes, so launching again re-enters
    **	SDL_main() against those stale globals and segfaults immediately --
    **	Block_Mouse() dereferences _Mouse->Screen, which points at freed memory.
    **
    **	Terminate the process instead so the next launch starts clean. _exit()
    **	rather than exit() because the static destructors belong to that same
    **	un-resettable global state and are not safe to run here; flush first so
    **	anything the game buffered on the way out still lands.
    */
    fflush(NULL);
    _exit(result);
}

package com.vanillara.redalert;

import android.content.ContentResolver;
import android.content.Context;
import android.net.Uri;

import androidx.documentfile.provider.DocumentFile;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Locale;

/**
 * Imports user-supplied Red Alert data into the app's private storage and
 * answers questions about what is installed.
 *
 * The native engine runs with its working directory set to
 * files/redalert-root and expects:
 *
 *   assets/redalert/allies/INSTALL/REDALERT.INI
 *   assets/redalert/allies/.../*.MIX
 *   assets/redalert/soviet/.../*.MIX
 *
 * Nothing is bundled in the APK. The importer is the only way data gets in.
 */
public final class GameDataStore {

    public static final String ROOT_DIR = "redalert-root";
    private static final String ASSETS_DIR = "assets";
    private static final String GAME_ASSETS_DIR = "redalert";

    public enum Side {
        ALLIES("allies", "Allied"),
        SOVIET("soviet", "Soviet");

        public final String folder;
        public final String displayName;

        Side(String folder, String displayName) {
            this.folder = folder;
            this.displayName = displayName;
        }
    }

    public static final class ImportResult {
        public final GameDataInspector.Status status;
        public final int importedFiles;
        public final long importedBytes;
        public final boolean configCreated;

        ImportResult(GameDataInspector.Status status, int importedFiles, long importedBytes,
                     boolean configCreated) {
            this.status = status;
            this.importedFiles = importedFiles;
            this.importedBytes = importedBytes;
            this.configCreated = configCreated;
        }
    }

    public static final class ImportException extends IOException {
        ImportException(String message) {
            super(message);
        }
    }

    public interface ProgressListener {
        void onProgress(String currentFile, int files, long bytes);
    }

    private static final class Counter {
        int files;
        long bytes;
    }

    private GameDataStore() {
    }

    /**
     * Prefer app-specific external storage so the folders are visible over USB
     * and to file managers. Fall back to internal storage when external
     * storage is unavailable.
     */
    private static File storageBase(Context context) {
        File external = context.getExternalFilesDir(null);
        if (external != null) {
            if (!external.isDirectory() && !external.mkdirs()) {
                return context.getFilesDir();
            }
            if (external.canWrite()) {
                return external;
            }
        }
        return context.getFilesDir();
    }

    public static File root(Context context) {
        return new File(storageBase(context), ROOT_DIR);
    }

    /**
     * Creates the drop folders and short README files on first launch so the
     * player knows exactly where to put the disc contents.
     */
    public static void ensureFolders(Context context) throws IOException {
        File root = root(context);
        File allies = sideDir(context, Side.ALLIES);
        File soviet = sideDir(context, Side.SOVIET);
        File alliesInstall = new File(allies, GameDataInspector.INSTALL_DIR);
        File sovietInstall = new File(soviet, GameDataInspector.INSTALL_DIR);

        File[] directories = {root, allies, alliesInstall, soviet, sovietInstall};
        for (File directory : directories) {
            if (!directory.isDirectory() && !directory.mkdirs()) {
                throw new IOException("Unable to create " + directory.getAbsolutePath());
            }
        }

        writeIfMissing(new File(root, "PUT_GAME_FILES_HERE.txt"),
            "VANILLARA GAME DATA\n"
                + "==================\n\n"
                + "This app does not include Red Alert game files. Copy your own\n"
                + "legally obtained Allied and Soviet disc/install contents into:\n\n"
                + "  " + allies.getAbsolutePath() + "\n"
                + "  " + soviet.getAbsolutePath() + "\n\n"
                + "Each folder should contain INSTALL\\REDALERT.INI and the .MIX files\n"
                + "(REDALERT.MIX, CONQUER.MIX, GENERAL.MIX, and so on).\n\n"
                + "Mount or extract ISO/BIN/CUE images first; disc images and archives\n"
                + "are not read by the game. After copying, open Vanillara and tap\n"
                + "\"Rescan\".\n");
        writeIfMissing(new File(allies, "PUT_ALLIED_FILES_HERE.txt"),
            "ALLIED RED ALERT DATA\n"
                + "=====================\n\n"
                + "Copy the contents of your Allied disc or full installation here.\n"
                + "Expected: INSTALL\\REDALERT.INI and the .MIX files from the disc.\n"
                + "Do not put .ISO, .BIN, or .CUE images here; mount or extract them first.\n");
        writeIfMissing(new File(soviet, "PUT_SOVIET_FILES_HERE.txt"),
            "SOVIET RED ALERT DATA\n"
                + "=====================\n\n"
                + "Copy the contents of your Soviet disc or full installation here.\n"
                + "Expected: INSTALL\\REDALERT.INI and the .MIX files from the disc.\n"
                + "Do not put .ISO, .BIN, or .CUE images here; mount or extract them first.\n");
    }

    private static void writeIfMissing(File file, String text) throws IOException {
        if (file.isFile()) {
            return;
        }
        try (OutputStream output = new FileOutputStream(file)) {
            output.write(text.getBytes("UTF-8"));
        }
    }

    public static File gameAssetsDir(Context context) {
        return new File(new File(root(context), ASSETS_DIR), GAME_ASSETS_DIR);
    }

    public static File sideDir(Context context, Side side) {
        return new File(gameAssetsDir(context), side.folder);
    }

    public static GameDataInspector.Status status(Context context, Side side) {
        return GameDataInspector.inspect(sideDir(context, side));
    }

    public static boolean isPlayable(Context context) {
        return status(context, Side.ALLIES).isPlayable()
            || status(context, Side.SOVIET).isPlayable();
    }

    /**
     * Creates the INI files the engine expects and reports whether at least one
     * side has the main game archive. Called right before the SDL activity
     * starts, and again from the setup screen for status.
     */
    public static boolean prepareForLaunch(Context context) {
        try {
            ensureFolders(context);
        } catch (IOException ignored) {
            // A read-only or full volume is reported by the setup screen.
        }
        boolean playable = false;
        for (Side side : Side.values()) {
            File dir = sideDir(context, side);
            GameDataInspector.Status status = GameDataInspector.inspect(dir);
            if (status.hasMix || side == Side.ALLIES) {
                try {
                    GameDataInspector.ensureConfig(dir);
                } catch (IOException ignored) {
                    // The status screen reports the missing data; the engine will
                    // also fail cleanly if its INI cannot be created.
                }
            }
            if (status.isPlayable()) {
                playable = true;
            }
        }
        return playable;
    }

    public static void clear(Context context) {
        GameDataInspector.deleteTree(root(context));
    }

    public static ImportResult importTree(Context context, Uri treeUri, Side side,
                                          ProgressListener listener) throws IOException {
        if (treeUri == null) {
            throw new ImportException("No folder was selected.");
        }
        DocumentFile tree = DocumentFile.fromTreeUri(context, treeUri);
        if (tree == null || !tree.isDirectory()) {
            throw new ImportException("The selected item is not a readable folder.");
        }

        DocumentFile source = resolveSource(tree, side);
        File sideDir = sideDir(context, side);
        File target = sideDir;
        String sourceName = source.getName();

package com.vanillara.redalert;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.ActivityNotFoundException;
import android.content.ClipData;
import android.content.ClipboardManager;
import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.os.SystemClock;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.TextView;
import android.widget.Toast;

import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * First screen: imports the player's own Red Alert files and launches the SDL
 * activity only after the data is present.
 */
public class SetupActivity extends Activity {

    private static final int REQUEST_ALLIES = 1001;
    private static final int REQUEST_SOVIET = 1002;

    private final Handler mainHandler = new Handler(Looper.getMainLooper());
    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    private TextView alliedStatus;
    private TextView sovietStatus;
    private TextView warning;
    private TextView busyLabel;
    private TextView progressText;
    private TextView dataPath;
    private LinearLayout progressContainer;
    private Button importAllied;
    private Button importSoviet;
    private Button copyPath;
    private Button rescan;
    private Button play;
    private Button clear;
    private Button help;
    private Button about;

    private boolean importing;
    private boolean canPlay;
    private long lastProgressAt;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_setup);

        alliedStatus = findViewById(R.id.allied_status);
        sovietStatus = findViewById(R.id.soviet_status);
        warning = findViewById(R.id.warning);
        busyLabel = findViewById(R.id.busy_label);
        progressText = findViewById(R.id.progress_text);
        progressContainer = findViewById(R.id.progress_container);
        dataPath = findViewById(R.id.data_path);
        importAllied = findViewById(R.id.import_allied);
        importSoviet = findViewById(R.id.import_soviet);
        copyPath = findViewById(R.id.copy_path);
        rescan = findViewById(R.id.rescan);
        play = findViewById(R.id.play);
        clear = findViewById(R.id.clear);
        help = findViewById(R.id.help);
        about = findViewById(R.id.about);

        try {
            GameDataStore.ensureFolders(this);
        } catch (Exception error) {
            // The status card below reports missing/unreadable data.
        }

        importAllied.setOnClickListener(v -> pickFolder(GameDataStore.Side.ALLIES));
        importSoviet.setOnClickListener(v -> pickFolder(GameDataStore.Side.SOVIET));
        copyPath.setOnClickListener(v -> copyDataPath());
        rescan.setOnClickListener(v -> {
            refreshStatus();
            Toast.makeText(this, "Folders rescanned", Toast.LENGTH_SHORT).show();
        });
        play.setOnClickListener(v -> launchGame());
        clear.setOnClickListener(v -> confirmClear());
        help.setOnClickListener(v -> showTextDialog(getString(R.string.import_help_title),
            getString(R.string.import_help_body)));
        about.setOnClickListener(v -> showTextDialog(getString(R.string.about),
            getString(R.string.about_body)));

        refreshStatus();
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (!importing) {
            refreshStatus();
        }
    }

    @Override
    protected void onDestroy() {
        executor.shutdownNow();
        super.onDestroy();
    }

    private void pickFolder(GameDataStore.Side side) {
        if (importing) {
            return;
        }
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION
            | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        try {
            startActivityForResult(intent,
                side == GameDataStore.Side.ALLIES ? REQUEST_ALLIES : REQUEST_SOVIET);
        } catch (ActivityNotFoundException exception) {
            showError("No file picker",
                "This device does not provide a folder picker. Install a file manager that supports "
                    + "Android's Storage Access Framework and try again.");
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode != REQUEST_ALLIES && requestCode != REQUEST_SOVIET) {
            return;
        }
        if (resultCode != RESULT_OK || data == null || data.getData() == null) {
            return;
        }

        Uri uri = data.getData();
        try {
            getContentResolver().takePersistableUriPermission(
                uri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
        } catch (SecurityException ignored) {
            // Some document providers grant only a transient permission. The
            // copy happens immediately, so that is still enough.
        }

        GameDataStore.Side side = requestCode == REQUEST_ALLIES
            ? GameDataStore.Side.ALLIES
            : GameDataStore.Side.SOVIET;
        startImport(side, uri);
    }

    private void startImport(GameDataStore.Side side, Uri uri) {
        importing = true;
        lastProgressAt = 0;
        setBusy(true, "Importing " + side.displayName + " data…");
        progressText.setText("Scanning the selected folder…");

        executor.execute(() -> {
            try {
                GameDataStore.ImportResult result = GameDataStore.importTree(
                    this, uri, side, (name, files, bytes) -> publishProgress(name, files, bytes));
                mainHandler.post(() -> finishImport(side, result, null));
            } catch (Throwable error) {
                mainHandler.post(() -> finishImport(side, null, error));
            }
        });
    }

    private void publishProgress(String name, int files, long bytes) {
        long now = SystemClock.uptimeMillis();
        if (now - lastProgressAt < 120) {
            return;
        }
        lastProgressAt = now;
        mainHandler.post(() -> {
            if (!importing) {
                return;
            }
            String shortName = name.length() > 44 ? "…" + name.substring(name.length() - 43) : name;
            progressText.setText(String.format(Locale.US, "%d files • %s\n%s",
                files, GameDataStore.formatBytes(bytes), shortName));
        });
    }

    private void finishImport(GameDataStore.Side side, GameDataStore.ImportResult result,
                              Throwable error) {
        importing = false;
        setBusy(false, null);
        refreshStatus();

        if (error != null) {
            String message = error.getMessage();
            if (message == null || message.isEmpty()) {
                message = error.toString();
            }
            showError("Import failed", message);
            return;
        }

        String message = String.format(Locale.US, "Imported %d files (%s).",
            result.importedFiles, GameDataStore.formatBytes(result.importedBytes));
        if (result.configCreated) {
            message += "\n\nA REDALERT.INI was created because the selected folder did not contain one.";
        }
        message += "\n\n" + side.displayName + " data is ready.";
        new AlertDialog.Builder(this)
            .setTitle("Import complete")
            .setMessage(message)
            .setPositiveButton(android.R.string.ok, null)
            .show();
    }

    private void setBusy(boolean busy, String label) {
        importing = busy;
        progressContainer.setVisibility(busy ? View.VISIBLE : View.GONE);
        if (label != null) {
            busyLabel.setText(label);
        }
        importAllied.setEnabled(!busy);
        importSoviet.setEnabled(!busy);
        copyPath.setEnabled(!busy);
        rescan.setEnabled(!busy);
        clear.setEnabled(!busy);
        help.setEnabled(!busy);
        about.setEnabled(!busy);
        play.setEnabled(!busy && canPlay);
    }

    private void refreshStatus() {
        dataPath.setText(GameDataStore.gameAssetsDir(this).getAbsolutePath());

        GameDataInspector.Status allied = GameDataStore.status(this, GameDataStore.Side.ALLIES);
        GameDataInspector.Status soviet = GameDataStore.status(this, GameDataStore.Side.SOVIET);

        alliedStatus.setText(describe(allied));
        sovietStatus.setText(describe(soviet));
        alliedStatus.setTextColor(getColor(allied.isPlayable()
            ? R.color.text_ok : allied.hasMix ? R.color.text_warning : R.color.text_secondary));
        sovietStatus.setTextColor(getColor(soviet.isPlayable()
            ? R.color.text_ok : soviet.hasMix ? R.color.text_warning : R.color.text_secondary));

        canPlay = allied.isPlayable() || soviet.isPlayable();
        play.setEnabled(canPlay && !importing);
        play.setText(canPlay ? R.string.play : R.string.play_needs_data);

        if (!allied.hasMix && !soviet.hasMix) {
            warning.setText("No game data found yet. Copy your Allied and Soviet files into the "
                + "folders above, then tap Rescan.");
        } else if (allied.isPlayable() && soviet.isPlayable()) {
            warning.setText("Allied and Soviet data are ready.");
        } else if (allied.isPlayable()) {
            warning.setText("Allied data is ready. Soviet data is missing or incomplete, so the "
                + "Soviet campaign and some movies may not work.");
        } else if (soviet.isPlayable()) {
            warning.setText("Soviet data is ready. Allied data is missing or incomplete, so the "
                + "Allied campaign and some movies may not work.");
        } else {
            warning.setText("Game files were found, but REDALERT.MIX is missing. Copy the complete "
                + "disc contents into the folders above.");
        }
    }

    private String describe(GameDataInspector.Status status) {
        if (!status.hasMix) {
            return getString(R.string.not_imported);
        }
        StringBuilder text = new StringBuilder();
        text.append(status.fileCount).append(" files • ")
            .append(GameDataStore.formatBytes(status.byteCount));
        if (status.hasMainMix) {
            text.append(" • ").append(getString(R.string.ready));
        } else {
            text.append(" • missing ").append(GameDataInspector.MAIN_MIX);
        }
        if (!status.hasConfig) {
            text.append(" • settings will be generated");
        }
        return text.toString();
    }

    private void copyDataPath() {
        String path = GameDataStore.gameAssetsDir(this).getAbsolutePath();
        ClipboardManager clipboard =
            (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboard != null) {
            clipboard.setPrimaryClip(ClipData.newPlainText("Vanillara game data path", path));
            Toast.makeText(this, "Path copied", Toast.LENGTH_SHORT).show();
        }
    }

    private void launchGame() {
        if (importing) {
            return;
        }
        if (!GameDataStore.prepareForLaunch(this)) {
            refreshStatus();
            showError("Game data missing",
                "Import the original Red Alert data before playing. " + GameDataInspector.MAIN_MIX
                    + " was not found in either the Allied or Soviet folder.");
            return;
        }
        startActivity(new Intent(this, RedAlertActivity.class));
    }

    private void confirmClear() {
        new AlertDialog.Builder(this)
            .setTitle("Clear imported data?")
            .setMessage("This removes the imported game files, saves, and options from this app. "
                + "Your original files are not affected.")
            .setNegativeButton(android.R.string.cancel, null)
            .setPositiveButton("Clear", (dialog, which) -> {
                GameDataStore.clear(this);
                try {
                    GameDataStore.ensureFolders(this);
                } catch (Exception error) {
                    showError("Unable to recreate folders", error.getMessage());
                }
                refreshStatus();
                Toast.makeText(this, "Imported data removed", Toast.LENGTH_SHORT).show();
            })
            .show();
    }

    private void showTextDialog(String title, String body) {
        new AlertDialog.Builder(this)
            .setTitle(title)
            .setMessage(body)
            .setPositiveButton(android.R.string.ok, null)
            .show();
    }

    private void showError(String title, String message) {
        new AlertDialog.Builder(this)
            .setTitle(title)
            .setMessage(message)
            .setPositiveButton(android.R.string.ok, null)
            .show();
    }
}

