private void chooseStorageLocation() {
    if (!GameDataStore.hasSharedStorageAccess(this)) {
        new AlertDialog.Builder(this)
            .setTitle("File access needed")
            .setMessage("Grant file access before choosing a storage location.")
            .setPositiveButton("Grant", (d,w) -> requestStorageAccess())
            .setNegativeButton(android.R.string.cancel, null)
            .show();
        return;
    }
    List<GameDataStore.Volume> volumes = GameDataStore.availableVolumes(this);
    if (volumes.size() == 1) {
        showError("No SD card", "No removable SD card was detected. Internal storage is the only option.");
        return;
    }
    String[] labels = new String[volumes.size()];
    int checked = 0;
    GameDataStore.Volume current = GameDataStore.currentVolume(this);
    for (int i = 0; i < volumes.size(); i++) {
        Volume v = volumes.get(i);
        long free = GameDataStore.freeBytes(v.root);
        labels[i] = v.label + (free >= 0 ? " — " + GameDataStore.formatBytes(free) + " free" : "");
        if (v.root.equals(current.root)) checked = i;
    }
    new AlertDialog.Builder(this)
        .setTitle("Storage location")
        .setSingleChoiceItems(labels, checked, (dialog, which) -> {
            dialog.dismiss();
            Volume selected = volumes.get(which);
            if (selected.root.equals(GameDataStore.currentVolume(this).root)) return;
            confirmRelocate(selected);
        })
        .setNegativeButton(android.R.string.cancel, null)
        .show();
}
