private static List<SafNode> listChildren(ContentResolver resolver, Uri treeUri, String parentId)
        throws IOException {
    Uri childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentId);
    List<SafNode> nodes = new ArrayList<>();
    try (Cursor cursor = resolver.query(childrenUri, DOCUMENT_PROJECTION, null, null, null)) {
        if (cursor == null) {
            throw new IOException("The selected folder could not be listed.");
        }
        int idIndex = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID);
        int nameIndex = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME);
        int mimeIndex = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE);
        while (cursor.moveToNext()) {
            String id = idIndex >= 0 ? cursor.getString(idIndex) : null;
            String name = nameIndex >= 0 ? cursor.getString(nameIndex) : null;
            String mime = mimeIndex >= 0 ? cursor.getString(mimeIndex) : null;
            if (id == null || name == null) continue;
            boolean directory = DocumentsContract.Document.MIME_TYPE_DIR.equals(mime);
            nodes.add(new SafNode(id, name, directory,
                DocumentsContract.buildDocumentUriUsingTree(treeUri, id)));
        }
    }
    return nodes;
}
