private void chooseStorageLocation() {
    if (!GameDataStore.hasSharedStorageAccess(this)) {
        new AlertDialog.Builder(this)
            .setTitle(R.string.storage_permission_title)
            .setMessage(R.string.storage_permission_message)
            .setPositiveButton(R.string.grant_access, (d, w) -> requestStorageAccess())
            .setNegativeButton(android.R.string.cancel, null)
            .show();
        return;
    }
    List<GameDataStore.Volume> volumes = GameDataStore.availableVolumes(this);
    if (volumes.size() <= 1) {
        showError(getString(R.string.no_sd_card_title), getString(R.string.no_sd_card_message));
        return;
    }
    GameDataStore.Volume current = GameDataStore.currentVolume(this);
    String[] labels = new String[volumes.size()];
    int checked = 0;
    for (int i = 0; i < volumes.size(); i++) {
        GameDataStore.Volume volume = volumes.get(i);
        long free = GameDataStore.freeBytes(volume.root);
        labels[i] = volume.label + (free >= 0
            ? " — " + GameDataStore.formatBytes(free) + " free" : "");
        if (volume.root.getAbsolutePath().equals(current.root.getAbsolutePath())) checked = i;
    }
    new AlertDialog.Builder(this)
        .setTitle(R.string.storage_location_title)
        .setSingleChoiceItems(labels, checked, (dialog, which) -> {
            dialog.dismiss();
            GameDataStore.Volume selected = volumes.get(which);
            if (selected.root.getAbsolutePath().equals(
                    GameDataStore.currentVolume(this).root.getAbsolutePath())) {
                return;
            }
            confirmRelocate(selected);
        })
        .setNegativeButton(android.R.string.cancel, null)
        .show();
}
